import type { AxiosResponse } from 'axios';

import apiClient from '@/config/apiClient';
import type { OTPPayload } from '@/types/apiRequests';
import type { SimpleResponse } from '@/types/apiResponses';

/**
 * Submit the 6-digit TOTP code generated by the CFM MFA app.
 */
export default function verifyOTP(
  data: OTPPayload,
): Promise<AxiosResponse<SimpleResponse>> {
  return apiClient.post('/auth/totp/verify', data);
}
